// Multiplication by Constant Optimization
// Compiler replaces C * X with shifts/adds/subs.

// Target: x * 10 (10 = 8 + 2)
int target_mul(int x) {
    return x * 10;
}

// Conceptual Compiler Optimization (Shift/Add sequence):
// 10x = (x * 8) + (x * 2)
int optimized_mul(int x) {
    return (x << 3) + (x << 1);
}

// Alternative: x * 7 (7 = 8 - 1)
// Fastest using Shift/Subtract:
int optimized_mul_seven(int x) {
    return (x << 3) - x;
}

// Performance Benefit: Shifts/Adds/Subs are often faster
// (fewer clock cycles) than general MUL instruction.
